/// How a window's display reads the values a swapchain presents.
enum class ColorSpace : std::int32_t {
    /// sRGB. Every window has it.
    Srgb = BFR_COLOR_SPACE_SRGB,
    /// scRGB: sRGB primaries, linear, values beyond 0 to 1.
    SrgbExtendedLinear = BFR_COLOR_SPACE_SRGB_EXTENDED_LINEAR,
    /// sRGB primaries and curve, values beyond 0 to 1.
    SrgbExtended = BFR_COLOR_SPACE_SRGB_EXTENDED,
    /// Display P3 with the sRGB curve.
    DisplayP3 = BFR_COLOR_SPACE_DISPLAY_P3,
    /// Display P3, linear.
    DisplayP3Linear = BFR_COLOR_SPACE_DISPLAY_P3_LINEAR,
    /// DCI-P3 with its own curve.
    DciP3 = BFR_COLOR_SPACE_DCI_P3,
    /// BT.709 with its curve.
    Bt709 = BFR_COLOR_SPACE_BT709,
    /// BT.709, linear.
    Bt709Linear = BFR_COLOR_SPACE_BT709_LINEAR,
    /// BT.2020, linear.
    Bt2020Linear = BFR_COLOR_SPACE_BT2020_LINEAR,
    /// HDR10: BT.2020 with the PQ (ST 2084) curve.
    Hdr10Pq = BFR_COLOR_SPACE_HDR10_PQ,
    /// BT.2020 with the HLG curve.
    Hdr10Hlg = BFR_COLOR_SPACE_HDR10_HLG,
    /// Dolby Vision.
    DolbyVision = BFR_COLOR_SPACE_DOLBY_VISION,
    /// Adobe RGB with its curve.
    AdobeRgb = BFR_COLOR_SPACE_ADOBE_RGB,
    /// Adobe RGB, linear.
    AdobeRgbLinear = BFR_COLOR_SPACE_ADOBE_RGB_LINEAR,
    /// Values reach the display as they are.
    PassThrough = BFR_COLOR_SPACE_PASS_THROUGH,
    /// The display's own space (AMD FreeSync 2).
    DisplayNative = BFR_COLOR_SPACE_DISPLAY_NATIVE,
};

/// value's name in bfr.yaml; empty for a value ColorSpace doesn't have.
[[nodiscard]] constexpr std::string_view name(ColorSpace value) {
    switch (value) {
    case ColorSpace::Srgb: return "srgb";
    case ColorSpace::SrgbExtendedLinear: return "srgb_extended_linear";
    case ColorSpace::SrgbExtended: return "srgb_extended";
    case ColorSpace::DisplayP3: return "display_p3";
    case ColorSpace::DisplayP3Linear: return "display_p3_linear";
    case ColorSpace::DciP3: return "dci_p3";
    case ColorSpace::Bt709: return "bt709";
    case ColorSpace::Bt709Linear: return "bt709_linear";
    case ColorSpace::Bt2020Linear: return "bt2020_linear";
    case ColorSpace::Hdr10Pq: return "hdr10_pq";
    case ColorSpace::Hdr10Hlg: return "hdr10_hlg";
    case ColorSpace::DolbyVision: return "dolby_vision";
    case ColorSpace::AdobeRgb: return "adobe_rgb";
    case ColorSpace::AdobeRgbLinear: return "adobe_rgb_linear";
    case ColorSpace::PassThrough: return "pass_through";
    case ColorSpace::DisplayNative: return "display_native";
    }
    return {};
}

/// How a window's display is turned relative to its natural orientation.
enum class DisplayRotation : std::int32_t {
    /// Not turned.
    None = BFR_DISPLAY_ROTATION_NONE,
    /// Turned 90 degrees clockwise.
    Rotate90 = BFR_DISPLAY_ROTATION_ROTATE_90,
    /// Turned 180 degrees.
    Rotate180 = BFR_DISPLAY_ROTATION_ROTATE_180,
    /// Turned 270 degrees clockwise.
    Rotate270 = BFR_DISPLAY_ROTATION_ROTATE_270,
    /// Mirrored, or left to the platform.
    Other = BFR_DISPLAY_ROTATION_OTHER,
};

/// value's name in bfr.yaml; empty for a value DisplayRotation doesn't have.
[[nodiscard]] constexpr std::string_view name(DisplayRotation value) {
    switch (value) {
    case DisplayRotation::None: return "none";
    case DisplayRotation::Rotate90: return "rotate_90";
    case DisplayRotation::Rotate180: return "rotate_180";
    case DisplayRotation::Rotate270: return "rotate_270";
    case DisplayRotation::Other: return "other";
    }
    return {};
}

/// How a swapchain presents. Which ones a window allows is in bfr_swapchain_caps.
enum class PresentMode : std::int32_t {
    /// Presents wait for vertical blank and queue up. Always available.
    Fifo = BFR_PRESENT_MODE_FIFO,
    /// As fifo, but a late frame presents at once, and may tear.
    FifoRelaxed = BFR_PRESENT_MODE_FIFO_RELAXED,
    /// Presents wait for vertical blank, and a newer frame replaces a waiting one.
    Mailbox = BFR_PRESENT_MODE_MAILBOX,
    /// Presents at once, and may tear.
    Immediate = BFR_PRESENT_MODE_IMMEDIATE,
};

/// value's name in bfr.yaml; empty for a value PresentMode doesn't have.
[[nodiscard]] constexpr std::string_view name(PresentMode value) {
    switch (value) {
    case PresentMode::Fifo: return "fifo";
    case PresentMode::FifoRelaxed: return "fifo_relaxed";
    case PresentMode::Mailbox: return "mailbox";
    case PresentMode::Immediate: return "immediate";
    }
    return {};
}

/// How a window blends a swapchain's alpha. Which ones a window allows is in bfr_swapchain_caps.
enum class AlphaMode : std::int32_t {
    /// The window ignores alpha.
    Opaque = BFR_ALPHA_MODE_OPAQUE,
    /// Colors are already multiplied by alpha.
    Premultiplied = BFR_ALPHA_MODE_PREMULTIPLIED,
    /// The window multiplies colors by alpha.
    Postmultiplied = BFR_ALPHA_MODE_POSTMULTIPLIED,
    /// The window system decides how alpha blends.
    Inherit = BFR_ALPHA_MODE_INHERIT,
};

/// value's name in bfr.yaml; empty for a value AlphaMode doesn't have.
[[nodiscard]] constexpr std::string_view name(AlphaMode value) {
    switch (value) {
    case AlphaMode::Opaque: return "opaque";
    case AlphaMode::Premultiplied: return "premultiplied";
    case AlphaMode::Postmultiplied: return "postmultiplied";
    case AlphaMode::Inherit: return "inherit";
    }
    return {};
}

/// What a queue runs.
enum class QueueType : std::int32_t {
    /// Graphics, compute and copies.
    Graphics = BFR_QUEUE_TYPE_GRAPHICS,
    /// Compute and copies.
    Compute = BFR_QUEUE_TYPE_COMPUTE,
    /// Copies alone.
    Copy = BFR_QUEUE_TYPE_COPY,
};

/// value's name in bfr.yaml; empty for a value QueueType doesn't have.
[[nodiscard]] constexpr std::string_view name(QueueType value) {
    switch (value) {
    case QueueType::Graphics: return "graphics";
    case QueueType::Compute: return "compute";
    case QueueType::Copy: return "copy";
    }
    return {};
}

/// What the backend said of a swapchain as an image was acquired or presented.
enum class SwapchainStatus : std::int32_t {
    /// It said nothing more than that the call succeeded.
    Matches = BFR_SWAPCHAIN_STATUS_MATCHES,
    /// It no longer matches its window exactly but still presents; Vulkan's VK_SUBOPTIMAL_KHR.
    /// bfr_resize_swapchain makes it match, when the caller chooses.
    Suboptimal = BFR_SWAPCHAIN_STATUS_SUBOPTIMAL,
};

/// value's name in bfr.yaml; empty for a value SwapchainStatus doesn't have.
[[nodiscard]] constexpr std::string_view name(SwapchainStatus value) {
    switch (value) {
    case SwapchainStatus::Matches: return "matches";
    case SwapchainStatus::Suboptimal: return "suboptimal";
    }
    return {};
}

/// What a tile mapping does to its region.
enum class TileMapping : std::int32_t {
    /// Maps the region to the memory's tiles.
    Map = BFR_TILE_MAPPING_MAP,
    /// Leaves the region with no memory; memory_tile is unused.
    Unmap = BFR_TILE_MAPPING_UNMAP,
};

/// value's name in bfr.yaml; empty for a value TileMapping doesn't have.
[[nodiscard]] constexpr std::string_view name(TileMapping value) {
    switch (value) {
    case TileMapping::Map: return "map";
    case TileMapping::Unmap: return "unmap";
    }
    return {};
}

