/// How a texture's memory is arranged for what the GPU does with it next. bfr_texture_barrier moves
/// a texture between layouts; BFR keeps no record of the one it is in. A copy queue's lists move a
/// texture only between undefined, copy_src and copy_dst, and a compute queue's never to or from
/// color_target, depth_stencil_target, depth_stencil_read, resolve_src or resolve_dst, as D3D12's
/// layouts for those queues allow; so a texture crosses between queues in a layout both kinds take.
enum class TextureLayout : std::int32_t {
    /// Its contents are not kept. Only a layout to move from.
    Undefined = BFR_TEXTURE_LAYOUT_UNDEFINED,
    /// Copies read it.
    CopySrc = BFR_TEXTURE_LAYOUT_COPY_SRC,
    /// Copies write it.
    CopyDst = BFR_TEXTURE_LAYOUT_COPY_DST,
    /// Shaders read it through the texture table.
    Sampled = BFR_TEXTURE_LAYOUT_SAMPLED,
    /// Shaders read and write it through the storage texture table.
    Storage = BFR_TEXTURE_LAYOUT_STORAGE,
    /// Rendering writes color to it.
    ColorTarget = BFR_TEXTURE_LAYOUT_COLOR_TARGET,
    /// Rendering tests and writes depth or stencil in it.
    DepthStencilTarget = BFR_TEXTURE_LAYOUT_DEPTH_STENCIL_TARGET,
    /// Rendering tests depth or stencil in it without writing, as a read_only depth-stencil
    /// attachment; shaders may sample it meanwhile.
    DepthStencilRead = BFR_TEXTURE_LAYOUT_DEPTH_STENCIL_READ,
    /// bfr_resolve_texture reads it.
    ResolveSrc = BFR_TEXTURE_LAYOUT_RESOLVE_SRC,
    /// bfr_resolve_texture writes it.
    ResolveDst = BFR_TEXTURE_LAYOUT_RESOLVE_DST,
};

/// value's name in bfr.yaml; empty for a value TextureLayout doesn't have.
[[nodiscard]] constexpr std::string_view name(TextureLayout value) {
    switch (value) {
    case TextureLayout::Undefined: return "undefined";
    case TextureLayout::CopySrc: return "copy_src";
    case TextureLayout::CopyDst: return "copy_dst";
    case TextureLayout::Sampled: return "sampled";
    case TextureLayout::Storage: return "storage";
    case TextureLayout::ColorTarget: return "color_target";
    case TextureLayout::DepthStencilTarget: return "depth_stencil_target";
    case TextureLayout::DepthStencilRead: return "depth_stencil_read";
    case TextureLayout::ResolveSrc: return "resolve_src";
    case TextureLayout::ResolveDst: return "resolve_dst";
    }
    return {};
}

