static_assert(sizeof(PipelineCacheRef) == sizeof(bfr_pipeline_cache) && alignof(PipelineCacheRef) == alignof(bfr_pipeline_cache) &&
              std::is_standard_layout_v<PipelineCacheRef> && std::is_trivially_copyable_v<PipelineCacheRef>);

/// How to create an instance.
struct InstanceDesc {
    Backend backend{};
    /// The API version the caller uses, in bfr_caps_info's terms (1, 2 is Vulkan 1.2), passed to
    /// the backend as it is. Below what BFR needs, which the backend's bfr_backend value states,
    /// bfr_create_instance fails with error_unsupported.
    std::uint32_t apiMajor{};
    /// The minor part of api_major's version.
    std::uint32_t apiMinor{};
    /// Enable the backend's validation layer. On Metal its messages go to the system log.
    bool validation{};
    /// May be empty.
    MessageCallback messageCallback{};
    /// The least severe message to send.
    MessageSeverity minSeverity{};
    /// Passed to message_callback, which may still be called after bfr_destroy_instance while a
    /// device lives.
    void* messageUserData{};
    /// The application's name, passed to the backend where it takes one; read during the call only.
    /// Empty is none.
    std::string_view applicationName{};
    /// The application's version, passed as given where the backend takes one.
    std::uint32_t applicationVersion{};
    /// The engine's name, as application_name.
    std::string_view engineName{};
    /// The engine's version, as application_version.
    std::uint32_t engineVersion{};
    /// Time the CPU spends in each call of the instance and its devices, which bfr_get_call_timings
    /// and bfr_get_instance_call_timings give. Off, it costs nothing; on, each call reads the clock
    /// twice.
    bool callTimings{};
};

/// An adapter, as an instance lists it. Nothing is opened.
struct AdapterInfo {
    std::string name{};
    AdapterType type{};
};

/// A window to present to. The caller's windowing code made it; the values stay valid while it is
/// open. All zero means no window.
struct Window {
    /// The window: an HWND on Windows, a Window XID on X11 (as a pointer), a wl_surface* on
    /// Wayland, a CAMetalLayer* on Apple.
    void* window{};
    /// The Display* on X11, the wl_display* on Wayland, the HINSTANCE on Windows; unused on Apple.
    void* display{};
    WindowSystem system{};
};

/// One queue a device opens.
struct QueueDesc {
    /// 0 to 1: its priority against the device's other queues, higher first; passed to the backend
    /// as given. Where bfr_caps_queues.ranks is 0 the backend doesn't rank a device's queues, so
    /// queues of different ranks fail the device with error_unsupported.
    float rank{};
    /// Its priority against every queue on the system; 0 is normal. A level the backend has no
    /// setting for fails the device with error_unsupported. Vulkan sets one level for all the
    /// queues of a kind, so there different levels in one kind fail the same way.
    QueueLevel level{};
};
static_assert(sizeof(QueueDesc) == sizeof(bfr_queue_desc) && alignof(QueueDesc) == alignof(bfr_queue_desc) &&
              std::is_standard_layout_v<QueueDesc> && std::is_trivially_copyable_v<QueueDesc>);
static_assert(offsetof(QueueDesc, rank) == offsetof(bfr_queue_desc, rank));
static_assert(offsetof(QueueDesc, level) == offsetof(bfr_queue_desc, level));

/// How to open an adapter. The device's queues are numbered: the graphics queues from 0, then the
/// compute queues, then the copy queues, in the order asked for here. A graphics queue's lists run
/// every call. A compute queue's run all but rendering, draws, the calls that set their state or
/// bind a graphics pipeline or an index buffer, and bfr_resolve_texture; a copy queue's run only
/// copies, barriers and bfr_write_timestamp. A copy between a buffer and a texture's depth or
/// stencil runs only in a graphics queue's lists, and one in a copy queue's has a buffer_offset
/// that is a multiple of 4. bfr_texture_layout says which layouts each kind's lists move a texture
/// between.
struct DeviceDesc {
    /// Index into the instance's adapter list.
    std::uint32_t adapter{};
    /// The window one of the device's queues must be able to present to, else it fails with
    /// error_present_unsupported; all zero opens it without asking.
    Window window{};
    /// The graphics queues to open, read during the call only; none is none. Fails with
    /// error_unsupported when the adapter has fewer; bfr_caps.queues says how many it has.
    std::span<const QueueDesc> graphicsQueues{};
    /// The compute queues to open, as graphics_queues says.
    std::span<const QueueDesc> computeQueues{};
    /// The copy queues to open, as graphics_queues says.
    std::span<const QueueDesc> copyQueues{};
    /// Command lists the device holds at once, across all its pools, and the most swapchains its
    /// recording lists render to at once; past it, calls fail with error_limit_reached. Room for
    /// them is made with the device, so recording and submitting never allocate. A bfr_submit of
    /// more lists than this fails with error_invalid_argument. 0 is none.
    std::uint32_t maxCommandLists{};
    /// Command pools the device holds at once, 0 for none; past it, bfr_create_command_pool fails
    /// with error_limit_reached.
    std::uint32_t maxCommandPools{};
    /// Swapchains the device holds at once, 0 for none; past it, bfr_create_swapchain fails with
    /// error_limit_reached.
    std::uint32_t maxSwapchains{};
    /// Slots in the sampled texture table bfr_pipeline describes, 0 for none. Made with the device,
    /// passed to the backend as given; bfr_caps_bindless.max_textures says how many the adapter
    /// holds, and more is the backend's to refuse, which Vulkan's validation does. D3D12 makes the
    /// three resource tables in one heap, so there they fail with error_limit_reached when together
    /// they are more than it holds.
    std::uint32_t maxBindlessTextures{};
    /// Slots in the storage texture table, as max_bindless_textures says;
    /// bfr_caps_bindless.max_storage_textures says how many the adapter holds.
    std::uint32_t maxBindlessStorageTextures{};
    /// Slots in the storage buffer table, as max_bindless_textures says;
    /// bfr_caps_bindless.max_storage_buffers says how many the adapter holds.
    std::uint32_t maxBindlessStorageBuffers{};
    /// Slots in the sampler table, passed as max_bindless_textures is;
    /// bfr_caps_bindless.max_samplers says how many the adapter holds.
    std::uint32_t maxBindlessSamplers{};
    /// Slots in the uniform buffer table, passed as max_bindless_textures is. Where
    /// bfr_caps_bindless.max_uniform_buffers is 0 the adapter has no such table, and more than 0
    /// fails with error_limit_reached.
    std::uint32_t maxBindlessUniformBuffers{};
    /// Timestamp pools the device holds at once, 0 for none; past it, bfr_create_timestamp_pool
    /// fails with error_limit_reached.
    std::uint32_t maxTimestampPools{};
    /// Query pools the device holds at once, 0 for none; past it, bfr_create_query_pool fails with
    /// error_limit_reached.
    std::uint32_t maxQueryPools{};
    /// Sparse memories the device holds at once, 0 for none; past it, bfr_create_sparse_memory
    /// fails with error_limit_reached.
    std::uint32_t maxSparseMemories{};
    /// The most texture regions and the most buffer regions one bfr_update_tile_mappings takes;
    /// room for them is made with the device, so mapping never allocates. More fails with
    /// error_invalid_argument. 0 is none.
    std::uint32_t maxTileMappings{};
    /// Slots in the acceleration structure table, of top structures, passed as
    /// max_bindless_textures is; bfr_caps_bindless.max_acceleration_structures says how many the
    /// adapter holds. Where that is 0 the device has no such table, and more than 0 fails with
    /// error_limit_reached. With 0 slots, top structures are made with none.
    std::uint32_t maxBindlessAccelerationStructures{};
    /// Slots in the partitioned top table bfr_pipeline states, of partitioned top structures; with
    /// 0, they are made with none. No limit names it: the backend says whether it holds the tables
    /// together. Where bfr_caps_features.partitioned_top is false, more than 0 fails with
    /// error_limit_reached.
    std::uint32_t maxBindlessPartitionedTops{};
    /// The most geometries one build takes, in bfr_build_acceleration_structure and
    /// bfr_get_acceleration_structure_sizes; a top structure's instances are one geometry. Room for
    /// them is made with the device, so building never allocates. More fails with
    /// error_limit_reached. 0 is none.
    std::uint32_t maxBuildGeometries{};
    /// Property pools the device holds at once, 0 for none; past it,
    /// bfr_create_acceleration_structure_property_pool fails with error_limit_reached.
    std::uint32_t maxAccelerationStructurePropertyPools{};
    /// Buffers the device holds at once, 0 for none; past it, bfr_create_buffer fails with
    /// error_limit_reached.
    std::uint32_t maxBuffers{};
    /// Textures the device holds at once, 0 for none; past it, bfr_create_texture fails with
    /// error_limit_reached.
    std::uint32_t maxTextures{};
    /// Shaders the device holds at once, 0 for none; past it, bfr_create_shader fails with
    /// error_limit_reached.
    std::uint32_t maxShaders{};
    /// Pipelines the device holds at once, 0 for none; past it, bfr_create_compute_pipeline,
    /// bfr_create_graphics_pipeline and bfr_create_ray_tracing_pipeline fails with
    /// error_limit_reached.
    std::uint32_t maxPipelines{};
    /// Pipeline caches the device holds at once, 0 for none; past it, bfr_create_pipeline_cache
    /// fails with error_limit_reached.
    std::uint32_t maxPipelineCaches{};
    /// Acceleration structures the device holds at once, 0 for none; past it,
    /// bfr_create_acceleration_structure fails with error_limit_reached.
    std::uint32_t maxAccelerationStructures{};
    /// The strides, in bytes, the device's indirect draws take, read during the call only. D3D12
    /// fixes a stride in the command signature it makes for them, so it makes one for each here and
    /// fails an indirect draw of any other with error_unsupported; Vulkan and Metal take any
    /// stride.
    std::span<const std::uint32_t> indirectStrides{};
};

/// How to create a swapchain.
struct SwapchainDesc {
    /// The window to present to.
    Window window{};
    /// The device's queue that presents its images; one the device lacks fails with
    /// error_invalid_argument.
    std::uint32_t queue{};
    /// Images to request, passed to the backend as given. bfr_swapchain_images says how many it
    /// made.
    std::uint32_t imageCount{};
    /// How to present; 0 is fifo. Fails with error_unsupported when the backend has no setting for
    /// it.
    PresentMode presentMode{};
    /// The images' format. Fails with error_unsupported when the backend has no setting for it with
    /// color_space.
    Format format{};
    /// How the display reads the images.
    ColorSpace colorSpace{};
    /// How the window blends alpha; 0 is opaque. Fails with error_unsupported when the backend has
    /// no setting for it.
    AlphaMode alphaMode{};
};

/// A swapchain's current images: their size and number, which are 0 while the window has no area,
/// and the format, color space, present mode and alpha mode in use, whether the desc set them or
/// left them at 0.
struct SwapchainImages {
    std::uint32_t width{};
    std::uint32_t height{};
    std::uint32_t count{};
    Format format{};
    ColorSpace colorSpace{};
    PresentMode presentMode{};
    AlphaMode alphaMode{};
};

/// One color target of a rendering: a texture with color_attachment usage, in layout color_target,
/// or the swapchain's acquired image when bfr_begin_rendering is given a swapchain and this is
/// attachment 0. Given a swapchain, attachment 0 may instead name a multisampled texture of the
/// swapchain's format, which is then resolved into the acquired image.
struct ColorAttachment {
    /// Null for the swapchain's image.
    TextureRef texture{};
    /// The mip level drawn to.
    std::uint32_t mipLevel{};
    /// The first layer drawn to; a cube's faces are its layers, and a 3D texture's depth slices are
    /// where bfr_caps_features.volume_color_targets.
    std::uint32_t layer{};
    /// The layers drawn to from layer. Vulkan and Metal draw one count of layers in a rendering:
    /// the depth-stencil attachment's where there is one, else color attachment 0's. On Vulkan each
    /// level and layer of a texture with an attachment usage is a view made with it.
    std::uint32_t layerCount = BFR_ONE_LAYER;
    /// What it holds at the start; 0 is load.
    LoadOp loadOp{};
    /// What becomes of it at the end; 0 is store.
    StoreOp storeOp{};
    /// Red, green, blue and alpha, 0 to 1, when load_op is clear.
    std::array<float, 4> clearColor{};
    /// The target holds integers: clear_color_integer applies instead. D3D12 clears with floats, so
    /// there a value a 32-bit float does not hold exactly fails with
    /// BFR_RESULT_ERROR_INVALID_ARGUMENT.
    bool clearInteger{};
    /// Red, green, blue and alpha bits, when load_op is clear; a signed format reads them as int32.
    std::array<std::uint32_t, 4> clearColorInteger{};
    /// A single-sample texture of texture's format and size, with color_attachment usage, in layout
    /// color_target, that texture's samples are resolved into as rendering ends; null for none, and
    /// null for the attachment the swapchain's image is resolved into. Non-integer formats average
    /// and integer ones take sample zero, as the backend resolves; bfr_format_caps.resolve says
    /// which formats resolve. It is resolved into at its mip level 0, from layer 0.
    TextureRef resolveTexture{};
};

/// The depth-stencil target of a rendering: a texture with depth_stencil usage, in layout
/// depth_stencil_target, or depth_stencil_read when read_only. Depth and stencil each load and
/// store as their ops say; an op of an aspect the format lacks is ignored.
struct DepthStencilAttachment {
    /// Null for no depth-stencil target.
    TextureRef texture{};
    /// The mip level drawn to.
    std::uint32_t mipLevel{};
    /// The first layer drawn to.
    std::uint32_t layer{};
    /// The layers drawn to from layer, as bfr_color_attachment's are.
    std::uint32_t layerCount = BFR_ONE_LAYER;
    /// 0 is load.
    LoadOp depthLoadOp{};
    /// 0 is store.
    StoreOp depthStoreOp{};
    /// 0 is load.
    LoadOp stencilLoadOp{};
    /// 0 is store.
    StoreOp stencilStoreOp{};
    /// 0 to 1, when depth_load_op is clear.
    float clearDepth{};
    /// When stencil_load_op is clear. The low 8 bits count.
    std::uint32_t clearStencil{};
    /// The rendering tests depth and stencil but never writes them, and shaders may sample the
    /// texture meanwhile; every op is then load and store. The pipelines drawn with write neither
    /// depth nor stencil.
    bool readOnly{};
    /// A single-sample texture of texture's format and size, with depth_stencil usage, in layout
    /// depth_stencil_target, that the samples are resolved into as rendering ends, by depth_resolve
    /// and stencil_resolve, at its mip level 0, from layer 0; null for none.
    TextureRef resolveTexture{};
    /// 0 is none.
    ResolveMode depthResolve{};
    /// 0 is none.
    ResolveMode stencilResolve{};
};

/// How to begin rendering: the attachments drawn to, all of one size and sample count, which the
/// graphics pipelines drawn with were made for. The first color_attachment_count color attachments
/// are drawn to, in the order the pipeline's targets are.
struct RenderingDesc {
    std::uint32_t colorAttachmentCount{};
    std::array<ColorAttachment, BFR_MAX_COLOR_TARGETS> colorAttachments{};
    DepthStencilAttachment depthStencil{};
    /// The occlusion pool the queries begun in this rendering count into; null for none. Metal
    /// binds it to the rendering; Vulkan and D3D12 take the pool at each bfr_begin_query, which
    /// names the same one.
    QueryPoolRef occlusionQueries{};
};

/// Where on the attachments the rendering lands, in pixels from the top left, and the depth range
/// it maps to. Clip space is the same on every backend: x right, y up, z 0 at the near plane and 1
/// at the far.
struct Viewport {
    float x{};
    float y{};
    float width{};
    float height{};
    float minDepth{};
    float maxDepth{};
};

/// A rectangle of pixels from the top left of the attachments.
struct Rect {
    std::uint32_t x{};
    std::uint32_t y{};
    std::uint32_t width{};
    std::uint32_t height{};
};

/// How to create a command pool.
struct CommandPoolDesc {
    /// The queue its lists record for, numbered as bfr_device_desc says.
    std::uint32_t queue{};
    /// Lists the pool holds, made with it from the device's max_command_lists. bfr_begin_commands
    /// hands them out in turn until bfr_reset_command_pool gives them back.
    std::uint32_t listCount{};
    /// Most bfr_push_constants calls the pool's lists record between resets, which a backend that
    /// copies push constants into memory (Metal) makes room for with the pool; 0 is none.
    std::uint32_t pushConstantUpdates{};
};

/// What the GPU does with a buffer. Set every use it will have.
struct BufferUsage {
    bool copySrc{};
    bool copyDst{};
    /// Shaders read it as constants, through its slot in the uniform buffer table. The table views
    /// the whole buffer, so its size is at most bfr_caps_limits.max_uniform_buffer_range.
    bool uniform{};
    /// Shaders read and write it. D3D12 views it in 32-bit values, so there its size must be a
    /// multiple of 4.
    bool storage{};
    /// Indexed draws read it.
    bool index{};
    /// Indirect draws, dispatches and traces read their arguments from it.
    bool indirect{};
    /// Acceleration structure builds read vertices, indices, transforms, boxes or instances from
    /// it. It starts at an address of the alignment those take.
    bool accelerationStructureInput{};
    /// Acceleration structure builds use it as scratch. It starts at an address that is a multiple
    /// of bfr_caps_ray_tracing.scratch_alignment, and of 256 where
    /// bfr_caps_features.partitioned_top, as a partitioned top structure's build takes.
    bool accelerationStructureScratch{};
    /// It holds shader binding table records. It starts at an address that is a multiple of
    /// bfr_caps_ray_tracing.table_alignment.
    bool shaderBindingTable{};
    /// bfr_serialize_acceleration_structure writes it and bfr_deserialize_acceleration_structure
    /// reads it. It starts at an address that is a multiple of 256.
    bool accelerationStructureData{};
    /// bfr_build_clusters writes structures into it, and moves and builds read them from it, where
    /// bfr_caps_features.cluster_acceleration_structure. It starts at an address that is a multiple
    /// of bfr_caps_ray_tracing.cluster_alignment, cluster_template_alignment and
    /// cluster_bottom_alignment.
    bool accelerationStructureStorage{};
};

/// How to create a buffer.
struct BufferDesc {
    /// Bytes.
    std::uint64_t size{};
    /// 0 is device.
    BufferMemory memory{};
    BufferUsage usage{};
    /// Made with no memory: bfr_update_tile_mappings maps sparse memory's tiles into it, as
    /// bfr_caps_sparse says. memory is device.
    bool sparse{};
    /// Its tiles may be mapped to memory other sparse resources' tiles are mapped to, where
    /// bfr_caps_sparse.aliased.
    bool sparseAliased{};
    /// One of bfr_caps_sparse.tile_bytes, or 0 where that list is empty; only when sparse.
    std::uint32_t tileBytes{};
};

/// One range copied from a source buffer to a destination buffer.
struct BufferCopy {
    /// Bytes into the source.
    std::uint64_t srcOffset{};
    /// Bytes into the destination.
    std::uint64_t dstOffset{};
    /// Bytes.
    std::uint64_t size{};
};
static_assert(sizeof(BufferCopy) == sizeof(bfr_buffer_copy) && alignof(BufferCopy) == alignof(bfr_buffer_copy) &&
              std::is_standard_layout_v<BufferCopy> && std::is_trivially_copyable_v<BufferCopy>);
static_assert(offsetof(BufferCopy, srcOffset) == offsetof(bfr_buffer_copy, src_offset));
static_assert(offsetof(BufferCopy, dstOffset) == offsetof(bfr_buffer_copy, dst_offset));
static_assert(offsetof(BufferCopy, size) == offsetof(bfr_buffer_copy, size));

/// What the GPU does with a texture. Set every use it will have.
struct TextureUsage {
    bool copySrc{};
    bool copyDst{};
    /// Shaders sample it.
    bool sampled{};
    /// Shaders read and write it.
    bool storage{};
    /// Rendering writes color to it.
    bool colorAttachment{};
    /// Rendering tests and writes depth or stencil in it.
    bool depthStencil{};
};

/// How to create a texture, in device memory. The CPU reaches it only by copies through a buffer.
/// More than one layer, or more than 6 for cube, makes an array texture, which shaders declare as
/// one.
struct TextureDesc {
    /// 0 is d2.
    TextureDimension dimension{};
    Format format{};
    /// Texels.
    std::uint32_t width{};
    /// Texels; 1 for d1.
    std::uint32_t height{};
    /// Texels for d3; 1 otherwise.
    std::uint32_t depth{};
    /// 1 for d3; for cube, a multiple of 6.
    std::uint32_t layers{};
    std::uint32_t mipLevels{};
    /// Samples per texel; 1 unless rendering multisamples it.
    std::uint32_t samples{};
    TextureUsage usage{};
    /// Made with no memory: bfr_update_tile_mappings maps sparse memory's tiles into it, as
    /// bfr_caps_sparse and bfr_get_sparse_format say.
    bool sparse{};
    /// Its tiles may be mapped to memory other sparse resources' tiles are mapped to, where
    /// bfr_caps_sparse.aliased.
    bool sparseAliased{};
    /// One of bfr_caps_sparse.tile_bytes, or 0 where that list is empty; only when sparse.
    std::uint32_t tileBytes{};
};

/// How to create a timestamp pool.
struct TimestampPoolDesc {
    /// The device's queue whose lists write it, numbered as bfr_device_desc says.
    std::uint32_t queue{};
    /// How many timestamps it holds.
    std::uint32_t count{};
};

/// How long a timestamp tick lasts, in the unit the backend gives: a period in nanoseconds or a
/// frequency in ticks per second. The other is 0.
struct TimestampRate {
    float periodNs{};
    std::uint64_t frequency{};
};

/// The statistics a pipeline_statistics pool counts. Task and mesh invocations where
/// bfr_caps_features.mesh_statistics.
struct PipelineStatisticsMask {
    bool inputVertices{};
    bool inputPrimitives{};
    bool vertexInvocations{};
    bool geometryInvocations{};
    bool geometryPrimitives{};
    bool clipInvocations{};
    bool clipPrimitives{};
    bool fragmentInvocations{};
    bool tessellationControl{};
    bool tessellationEvaluationInvocations{};
    bool computeInvocations{};
    bool taskInvocations{};
    bool meshInvocations{};
};

/// How to create a query pool.
struct QueryPoolDesc {
    /// What its queries count.
    QueryType type{};
    /// How many queries it holds.
    std::uint32_t count{};
    /// Read only for pipeline_statistics.
    PipelineStatisticsMask statistics{};
};

/// Where a pool's results land in the buffer bfr_resolve_queries writes, as the backend lays them
/// out: stride bytes for each query, and in each, the 64-bit value of an occlusion or
/// mesh_primitives_generated query at value, and each statistic of a pipeline_statistics query at
/// its offset, indexed by bfr_pipeline_statistic. BFR_NO_OFFSET where the results hold no such
/// value.
struct QueryLayout {
    std::uint32_t stride{};
    std::uint32_t value{};
    std::array<std::uint32_t, BFR_PIPELINE_STATISTIC_COUNT> statistics{};
};

/// A GPU timestamp and a host clock's reading taken together, so GPU ticks can be placed on the
/// host's timeline.
struct CalibratedTimestamps {
    std::uint64_t gpu{};
    std::uint64_t host{};
    /// How far apart the two readings may be, where deviation_given.
    std::uint64_t maxDeviationNs{};
    /// The backend gave max_deviation_ns.
    bool deviationGiven{};
};

/// The CPU time one kind of call has taken, read from std::chrono::steady_clock around each call:
/// how many there were, their nanoseconds in all, and the longest one's.
struct CallTiming {
    std::uint64_t count{};
    std::uint64_t totalNs{};
    std::uint64_t maxNs{};
};

/// Where a buffer is in the bindless tables bfr_pipeline states, from creation to destruction: the
/// index shaders use. A table the buffer's usage does not set has no slot for it, and reads
/// BFR_NO_SLOT.
struct BufferSlots {
    /// Its index in the storage buffer table; only with storage usage.
    std::uint32_t storage{};
    /// Its index in the uniform buffer table; only with uniform usage.
    std::uint32_t uniform{};
};

/// Where a texture is in the bindless tables bfr_pipeline states, from creation to destruction: the
/// index shaders use. A table the texture's usage does not set has no slot for it, and reads
/// BFR_NO_SLOT.
struct TextureSlots {
    /// Its index in the texture table; only with sampled usage.
    std::uint32_t sampled{};
    /// Its index in the storage texture table; only with storage usage.
    std::uint32_t storage{};
};

/// The mip levels and layers of a texture a barrier moves: mip_count levels from mip_level, and
/// layer_count layers from layer, in every plane. Counts pass through as given; 0 is no count
/// Vulkan takes. A 3D texture has one layer, so a barrier moves every depth slice of its levels.
struct TextureRange {
    std::uint32_t mipLevel{};
    std::uint32_t mipCount = BFR_REMAINING;
    std::uint32_t layer{};
    std::uint32_t layerCount = BFR_REMAINING;
};

/// One region copied between a buffer and one layer and mip level of a single-sampled texture.
/// bytes_per_row is a multiple of the format's block bytes and, when it is not 0, of
/// bfr_caps_limits.copy_row_pitch_alignment; buffer_offset a multiple of the block bytes and, when
/// it is not 0, of copy_offset_alignment. rows_per_image is at least height and a multiple of the
/// block height. A depth or stencil aspect copies its whole mip level, with buffer_offset a
/// multiple of 4, and takes 4 bytes a texel for depth, 2 for a 16-bit depth, and 1 for stencil.
struct BufferTextureCopy {
    /// Bytes into the buffer.
    std::uint64_t bufferOffset{};
    /// Bytes between the starts of two rows of texel blocks in the buffer.
    std::uint64_t bytesPerRow{};
    /// Rows of texels between the starts of two depth slices in the buffer.
    std::uint32_t rowsPerImage{};
    std::uint32_t mipLevel{};
    std::uint32_t layer{};
    TextureAspect aspect{};
    std::uint32_t x{};
    std::uint32_t y{};
    std::uint32_t z{};
    /// Texels.
    std::uint32_t width{};
    /// Texels.
    std::uint32_t height{};
    /// Texels.
    std::uint32_t depth{};
};
static_assert(sizeof(BufferTextureCopy) == sizeof(bfr_buffer_texture_copy) && alignof(BufferTextureCopy) == alignof(bfr_buffer_texture_copy) &&
              std::is_standard_layout_v<BufferTextureCopy> && std::is_trivially_copyable_v<BufferTextureCopy>);
static_assert(offsetof(BufferTextureCopy, bufferOffset) == offsetof(bfr_buffer_texture_copy, buffer_offset));
static_assert(offsetof(BufferTextureCopy, bytesPerRow) == offsetof(bfr_buffer_texture_copy, bytes_per_row));
static_assert(offsetof(BufferTextureCopy, rowsPerImage) == offsetof(bfr_buffer_texture_copy, rows_per_image));
static_assert(offsetof(BufferTextureCopy, mipLevel) == offsetof(bfr_buffer_texture_copy, mip_level));
static_assert(offsetof(BufferTextureCopy, layer) == offsetof(bfr_buffer_texture_copy, layer));
static_assert(offsetof(BufferTextureCopy, aspect) == offsetof(bfr_buffer_texture_copy, aspect));
static_assert(offsetof(BufferTextureCopy, x) == offsetof(bfr_buffer_texture_copy, x));
static_assert(offsetof(BufferTextureCopy, y) == offsetof(bfr_buffer_texture_copy, y));
static_assert(offsetof(BufferTextureCopy, z) == offsetof(bfr_buffer_texture_copy, z));
static_assert(offsetof(BufferTextureCopy, width) == offsetof(bfr_buffer_texture_copy, width));
static_assert(offsetof(BufferTextureCopy, height) == offsetof(bfr_buffer_texture_copy, height));
static_assert(offsetof(BufferTextureCopy, depth) == offsetof(bfr_buffer_texture_copy, depth));

/// One region copied between two textures of one format and sample count, from one layer and mip
/// level to another, every aspect of it. A depth-stencil or multisampled texture copies its whole
/// mip level.
struct TextureCopy {
    std::uint32_t srcMipLevel{};
    std::uint32_t srcLayer{};
    std::uint32_t srcX{};
    std::uint32_t srcY{};
    std::uint32_t srcZ{};
    std::uint32_t dstMipLevel{};
    std::uint32_t dstLayer{};
    std::uint32_t dstX{};
    std::uint32_t dstY{};
    std::uint32_t dstZ{};
    /// Texels.
    std::uint32_t width{};
    /// Texels.
    std::uint32_t height{};
    /// Texels.
    std::uint32_t depth{};
};
static_assert(sizeof(TextureCopy) == sizeof(bfr_texture_copy) && alignof(TextureCopy) == alignof(bfr_texture_copy) &&
              std::is_standard_layout_v<TextureCopy> && std::is_trivially_copyable_v<TextureCopy>);
static_assert(offsetof(TextureCopy, srcMipLevel) == offsetof(bfr_texture_copy, src_mip_level));
static_assert(offsetof(TextureCopy, srcLayer) == offsetof(bfr_texture_copy, src_layer));
static_assert(offsetof(TextureCopy, srcX) == offsetof(bfr_texture_copy, src_x));
static_assert(offsetof(TextureCopy, srcY) == offsetof(bfr_texture_copy, src_y));
static_assert(offsetof(TextureCopy, srcZ) == offsetof(bfr_texture_copy, src_z));
static_assert(offsetof(TextureCopy, dstMipLevel) == offsetof(bfr_texture_copy, dst_mip_level));
static_assert(offsetof(TextureCopy, dstLayer) == offsetof(bfr_texture_copy, dst_layer));
static_assert(offsetof(TextureCopy, dstX) == offsetof(bfr_texture_copy, dst_x));
static_assert(offsetof(TextureCopy, dstY) == offsetof(bfr_texture_copy, dst_y));
static_assert(offsetof(TextureCopy, dstZ) == offsetof(bfr_texture_copy, dst_z));
static_assert(offsetof(TextureCopy, width) == offsetof(bfr_texture_copy, width));
static_assert(offsetof(TextureCopy, height) == offsetof(bfr_texture_copy, height));
static_assert(offsetof(TextureCopy, depth) == offsetof(bfr_texture_copy, depth));

/// How to create a sampler. Every member reaches the backend as it is; the backend's rules for them
/// hold, such as Vulkan's for unnormalized coordinates: min and mag filter equal, mip filter
/// nearest, both LODs 0, U and V clamp, no anisotropy and no compare.
struct SamplerDesc {
    /// 0 is nearest.
    Filter magFilter{};
    Filter minFilter{};
    Filter mipFilter{};
    /// 0 is repeat.
    AddressMode addressU{};
    AddressMode addressV{};
    AddressMode addressW{};
    /// Added to the LOD; other than 0 needs bfr_caps_features.sampler_lod_bias.
    float lodBias{};
    float minLod{};
    /// 0 samples mip 0 only.
    float maxLod{};
    /// 0 is none; up to bfr_caps_limits.max_sampler_anisotropy.
    std::uint32_t maxAnisotropy{};
    SamplerReduction reduction{};
    /// With reduction compare.
    CompareOp compareOp{};
    /// Red, green, blue and alpha a clamp_to_border read returns; all 0 is transparent black. Other
    /// than (0,0,0,0), (0,0,0,1) and (1,1,1,1) needs bfr_caps_features.sampler_custom_border_color.
    std::array<float, 4> borderColor{};
    /// The texture holds integers: border_color_integer applies instead;
    /// bfr_caps_features.sampler_integer_border_color.
    bool borderInteger{};
    /// Red, green, blue and alpha bits; a signed format reads them as int32.
    std::array<std::uint32_t, 4> borderColorInteger{};
    /// Coordinates in texels, not 0 to 1; bfr_caps_features.sampler_unnormalized_coordinates.
    bool unnormalizedCoordinates{};
    /// The LOD averaged across a quad; bfr_caps_features.sampler_lod_average.
    bool lodAverage{};
};

/// One shader stage: bytecode for the backend the device runs on, and the name of the function in
/// it to run.
struct ShaderCode {
    /// Read during the call only.
    std::span<const std::uint8_t> code{};
    std::string_view entryPoint{};
};

/// How a graphics pipeline turns primitives into fragments.
struct RasterState {
    CullMode cull{};
    FrontFace frontFace{};
    FillMode fill{};
    /// Clamps depth to the viewport's range instead of clipping to it.
    bool depthClamp{};
    /// Added to each fragment's depth, in units of the depth format's smallest step. D3D12 takes
    /// whole numbers only, so there a fraction fails with BFR_RESULT_ERROR_INVALID_ARGUMENT.
    float depthBias{};
    /// Added to each fragment's depth, times its depth slope.
    float depthBiasSlope{};
    /// The most the bias may add; 0 is no limit.
    float depthBiasClamp{};
};

/// The stencil test for triangles facing one way.
struct StencilFace {
    /// When the stencil test fails.
    StencilOp fail{};
    /// When the stencil and depth tests pass.
    StencilOp pass{};
    /// When the stencil test passes and the depth test fails.
    StencilOp depthFail{};
    /// Reference value against stored.
    CompareOp compare{};
    /// The bits compared. The low 8 bits count.
    std::uint32_t readMask{};
    /// The bits written. The low 8 bits count.
    std::uint32_t writeMask{};
};

/// How a graphics pipeline tests depth and stencil. Off by default; the pipeline then needs no
/// depth-stencil target.
struct DepthStencilState {
    bool depthTest{};
    /// Fragments that pass write their depth.
    bool depthWrite{};
    /// New depth against stored.
    CompareOp depthCompare{};
    bool stencilTest{};
    StencilFace front{};
    StencilFace back{};
};

/// How a graphics pipeline blends a fragment into one color target. With enable false the
/// fragment's color replaces the target's, in the channels write_mask names.
struct BlendState {
    bool enable{};
    BlendFactor srcColor{};
    BlendFactor dstColor{};
    BlendOp colorOp{};
    BlendFactor srcAlpha{};
    BlendFactor dstAlpha{};
    BlendOp alphaOp{};
    /// Which channels are written: bit 0 red, 1 green, 2 blue, 3 alpha. Bits above 3 are ignored.
    std::uint32_t writeMask{};
};

/// One color target a graphics pipeline renders to.
struct ColorTarget {
    Format format{};
    BlendState blend{};
};

/// One shader of a ray tracing pipeline, run at stage.
struct RayTracingShader {
    RayTracingStage stage{};
    ShaderRef shader{};
};
static_assert(sizeof(RayTracingShader) == sizeof(bfr_ray_tracing_shader) && alignof(RayTracingShader) == alignof(bfr_ray_tracing_shader) &&
              std::is_standard_layout_v<RayTracingShader> && std::is_trivially_copyable_v<RayTracingShader>);
static_assert(offsetof(RayTracingShader, stage) == offsetof(bfr_ray_tracing_shader, stage));
static_assert(offsetof(RayTracingShader, shader) == offsetof(bfr_ray_tracing_shader, shader));

/// Shaders, by index into the pipeline's shaders, that a binding table record names by its group's
/// identifier; no_shader is none.
struct RayTracingGroup {
    RayTracingGroupType type{};
    std::uint32_t general{};
    std::uint32_t closestHit{};
    std::uint32_t anyHit{};
    std::uint32_t intersection{};
};
static_assert(sizeof(RayTracingGroup) == sizeof(bfr_ray_tracing_group) && alignof(RayTracingGroup) == alignof(bfr_ray_tracing_group) &&
              std::is_standard_layout_v<RayTracingGroup> && std::is_trivially_copyable_v<RayTracingGroup>);
static_assert(offsetof(RayTracingGroup, type) == offsetof(bfr_ray_tracing_group, type));
static_assert(offsetof(RayTracingGroup, general) == offsetof(bfr_ray_tracing_group, general));
static_assert(offsetof(RayTracingGroup, closestHit) == offsetof(bfr_ray_tracing_group, closest_hit));
static_assert(offsetof(RayTracingGroup, anyHit) == offsetof(bfr_ray_tracing_group, any_hit));
static_assert(offsetof(RayTracingGroup, intersection) == offsetof(bfr_ray_tracing_group, intersection));

/// How to create a ray tracing pipeline: at least one ray generation shader, its own or a
/// library's. max_payload_size and max_attribute_size are the largest payload and hit attributes
/// its shaders declare, passed to backends that take them. Rays trace recursively to
/// max_recursion_depth, at most bfr_caps_ray_tracing's; at 0 ray generation traces none. With
/// library, it is a pipeline library, where bfr_caps_features.ray_tracing_pipeline_library: never
/// bound, only linked into pipelines that name it in libraries. A linked library's shaders and
/// groups follow the pipeline's own, in the order libraries names them, so group indices count on
/// past its groups; each library was made with the same max_recursion_depth, max_payload_size and
/// max_attribute_size, and with capture_replay where the pipeline is.
struct RayTracingPipelineDesc {
    /// Read during the call only.
    std::span<const RayTracingShader> shaders{};
    /// Read during the call only.
    std::span<const RayTracingGroup> groups{};
    std::uint32_t maxRecursionDepth{};
    std::uint32_t maxPayloadSize{};
    std::uint32_t maxAttributeSize{};
    /// Where the pipeline is looked for, and added on a miss; null is none.
    PipelineCacheRef cache{};
    /// The bytes of stack its traces take, large enough for every trace it makes
    /// (bfr_get_ray_tracing_stack_size gives each shader's); 0 leaves the backend's own size.
    std::uint64_t stackSize{};
    bool library{};
    /// Read during the call only.
    std::span<const PipelineRef> libraries{};
    /// Its groups' identifiers may be captured, by bfr_get_capture_replay_identifiers, and
    /// replayed, where bfr_caps_features.ray_tracing_capture_replay.
    bool captureReplay{};
    /// None, or the identifiers bfr_get_capture_replay_identifiers gave for every group of groups,
    /// in order, bfr_caps_ray_tracing.capture_replay_identifier_size bytes each, of a pipeline made
    /// from the same desc: its groups then have the identifiers that pipeline's had. With
    /// capture_replay. Where bfr_caps_features.ray_tracing_capture_replay_mixed is false, a device
    /// makes none with them unless its first ray tracing pipeline had them, and none with them
    /// while it makes one without. Read during the call only.
    std::span<const std::uint8_t> replayIdentifiers{};
    /// Its traces take the opacity micromaps structures hold, where
    /// bfr_caps_features.opacity_micromap.
    bool allowOpacityMicromaps{};
    /// Its traces are at a time, of structures with motion, where
    /// bfr_caps_features.ray_tracing_motion.
    bool allowMotion{};
    /// Its traces may reach cluster bottom structures, which they must be made with to, where
    /// bfr_caps_features.cluster_acceleration_structure.
    bool allowClusters{};
};

/// Records in a shader binding table: size bytes from offset in buffer, which has
/// shader_binding_table usage, stride bytes apart. offset is a multiple of
/// bfr_caps_ray_tracing.table_alignment, stride of identifier_alignment and at most
/// max_shader_group_stride. A null buffer is no region.
struct ShaderTableRegion {
    BufferRef buffer{};
    std::uint64_t offset{};
    std::uint64_t size{};
    std::uint64_t stride{};
};

/// width by height by depth rays, within bfr_caps_ray_tracing.max_trace_rays and bfr_caps_compute's
/// max_workgroup_count times max_workgroup_size in each dimension. ray_generation is given, one
/// record, its size equal to its stride.
struct TraceRaysDesc {
    ShaderTableRegion rayGeneration{};
    ShaderTableRegion miss{};
    ShaderTableRegion hit{};
    ShaderTableRegion callable{};
    std::uint32_t width{};
    std::uint32_t height{};
    std::uint32_t depth{};
};

/// How to create a compute pipeline.
struct ComputePipelineDesc {
    ShaderCode compute{};
    /// Threads in each workgroup, as the shader declares them; a dispatch counts workgroups.
    std::array<std::uint32_t, 3> workgroupSize{};
    /// Where the pipeline is looked for, and added on a miss; null is none.
    PipelineCacheRef cache{};
};

/// How to create a graphics pipeline. Vertices are pulled: the vertex shader reads them by index
/// from buffers; the pipeline takes no vertex layout.
struct GraphicsPipelineDesc {
    ShaderCode vertex{};
    /// A code_size of 0 is no fragment shader; the pipeline writes depth alone.
    ShaderCode fragment{};
    /// Task and mesh shaders in place of vertices: with a mesh shader, the pipeline draws by
    /// bfr_draw_mesh, vertex has a code_size of 0, and topology and primitive_restart are unused.
    /// It needs bfr_caps_features.mesh_shader, and a task shader bfr_caps_features.task_shader; a
    /// code_size of 0 is none. With a task shader, the mesh shader reads no draw index.
    ShaderCode task{};
    /// Threads in each task workgroup, as the shader declares them.
    std::array<std::uint32_t, 3> taskWorkgroupSize{};
    ShaderCode mesh{};
    /// Threads in each mesh workgroup, as the shader declares them.
    std::array<std::uint32_t, 3> meshWorkgroupSize{};
    /// What its draws assemble until bfr_set_topology.
    Topology topology{};
    PrimitiveRestart primitiveRestart{};
    RasterState raster{};
    DepthStencilState depthStencil{};
    /// How many of color_targets are used, at most max_color_targets.
    std::uint32_t colorTargetCount{};
    /// The targets the pipeline renders to, in attachment order.
    std::array<ColorTarget, BFR_MAX_COLOR_TARGETS> colorTargets{};
    /// undefined is no depth-stencil target.
    Format depthStencilFormat{};
    /// Samples per pixel of every target; 1 is no multisampling.
    std::uint32_t samples{};
    /// The fragment's alpha sets how many samples it covers.
    bool alphaToCoverage{};
    /// The samples written, bit i for sample i; bits from samples up are ignored. Leaving one of
    /// the low samples bits clear needs bfr_caps_features.sample_mask.
    std::uint64_t sampleMask{};
    /// The fragment's alpha becomes 1 after coverage is taken from it, where
    /// bfr_caps_features.alpha_to_one.
    bool alphaToOne{};
    /// The fraction of samples, 0 to 1, shaded apart; above 0 shades per sample, where
    /// bfr_caps_features.sample_rate_shading.
    float minSampleShading{};
    /// Where the pipeline is looked for, and added on a miss; null is none.
    PipelineCacheRef cache{};
};

/// How to create a pipeline cache.
struct PipelineCacheDesc {
    /// Bytes bfr_get_pipeline_cache_data gave before, read during the call only.
    std::span<const std::uint8_t> data{};
};

/// A point on a queue's timeline, which bfr_submit writes and the GPU passes once what was
/// submitted has run. An all-zero token has already completed.
struct Token {
    /// Index of the queue on the device, numbered as bfr_device_desc says.
    std::uint32_t queue{};
    std::uint64_t value{};
};
static_assert(sizeof(Token) == sizeof(bfr_token) && alignof(Token) == alignof(bfr_token) &&
              std::is_standard_layout_v<Token> && std::is_trivially_copyable_v<Token>);
static_assert(offsetof(Token, queue) == offsetof(bfr_token, queue));
static_assert(offsetof(Token, value) == offsetof(bfr_token, value));

/// What to send to a queue.
struct SubmitDesc {
    /// The queue to send to, numbered as bfr_device_desc says.
    std::uint32_t queue{};
    /// Recorded from pools on the same queue; the GPU runs them in this order.
    std::span<const CommandList> commandLists{};
    /// The GPU passes these before it runs the lists.
    std::span<const Token> waits{};
};

/// How to create sparse memory, for the tiles of resources like texture and buffer, either of which
/// may be null but not both: Vulkan takes the memory's type from their requirements, and D3D12,
/// where bfr_caps_sparse.mixed_resources is false, the one kind of resource its heap holds. A
/// resource mapped to it later must take what they took, as each backend says.
struct SparseMemoryDesc {
    /// Bytes.
    std::uint64_t size{};
    /// One of bfr_caps_sparse.tile_bytes, or 0 where that list is empty.
    std::uint32_t tileBytes{};
    TextureRef texture{};
    BufferRef buffer{};
};

/// A tile's size, in texels.
struct TileShape {
    std::uint32_t width{};
    std::uint32_t height{};
    std::uint32_t depth{};
};

/// How one aspect of a sparse texture is cut into tiles, as the backend says. Mip levels from
/// first_tail_mip on are its tail, mapped as tiles of tail_bytes rather than by region.
struct TextureTiling {
    /// Bytes in one tile.
    std::uint64_t tileBytes{};
    TileShape shape{};
    std::uint32_t firstTailMip{};
    /// Bytes of one layer's tail.
    std::uint64_t tailBytes{};
    /// Bytes between the starts of two layers' tails; 0 where the backend gives none.
    std::uint64_t tailStride{};
    /// Every layer shares one tail, mapped at layer 0.
    bool singleTail{};
};

/// How a sparse buffer is cut into tiles.
struct BufferTiling {
    /// Bytes in one tile.
    std::uint64_t tileBytes{};
};

/// The texture a bfr_get_sparse_format call asks about, as bfr_texture_desc would make it.
struct SparseFormatDesc {
    Format format{};
    TextureDimension dimension{};
    std::uint32_t samples{};
    TextureUsage usage{};
    TextureAspect aspect{};
    /// As bfr_texture_desc.tile_bytes.
    std::uint32_t tileBytes{};
};

/// Whether a sparse texture of a format can be made, and its tiles' shape.
struct SparseFormat {
    bool supported{};
    TileShape shape{};
    /// Every layer shares one tail.
    bool singleTail{};
    /// Every mip level not a whole number of tiles is in the tail.
    bool alignedMipSize{};
};

/// One region of a sparse texture mapped to memory or unmapped. Below the tail the region is x, y,
/// z, width, height and depth, in tiles of the mip level; from bfr_texture_tiling.first_tail_mip
/// on, it is tail_tiles tiles from tail_tile in the layer's tail. memory_tile is where in memory,
/// in the texture's tiles.
struct TextureTileRegion {
    /// 0 is map.
    TileMapping mapping{};
    TextureAspect aspect{};
    std::uint32_t mipLevel{};
    std::uint32_t layer{};
    std::uint32_t x{};
    std::uint32_t y{};
    std::uint32_t z{};
    std::uint32_t width{};
    std::uint32_t height{};
    std::uint32_t depth{};
    std::uint64_t tailTile{};
    std::uint64_t tailTiles{};
    std::uint64_t memoryTile{};
};
static_assert(sizeof(TextureTileRegion) == sizeof(bfr_texture_tile_region) && alignof(TextureTileRegion) == alignof(bfr_texture_tile_region) &&
              std::is_standard_layout_v<TextureTileRegion> && std::is_trivially_copyable_v<TextureTileRegion>);
static_assert(offsetof(TextureTileRegion, mapping) == offsetof(bfr_texture_tile_region, mapping));
static_assert(offsetof(TextureTileRegion, aspect) == offsetof(bfr_texture_tile_region, aspect));
static_assert(offsetof(TextureTileRegion, mipLevel) == offsetof(bfr_texture_tile_region, mip_level));
static_assert(offsetof(TextureTileRegion, layer) == offsetof(bfr_texture_tile_region, layer));
static_assert(offsetof(TextureTileRegion, x) == offsetof(bfr_texture_tile_region, x));
static_assert(offsetof(TextureTileRegion, y) == offsetof(bfr_texture_tile_region, y));
static_assert(offsetof(TextureTileRegion, z) == offsetof(bfr_texture_tile_region, z));
static_assert(offsetof(TextureTileRegion, width) == offsetof(bfr_texture_tile_region, width));
static_assert(offsetof(TextureTileRegion, height) == offsetof(bfr_texture_tile_region, height));
static_assert(offsetof(TextureTileRegion, depth) == offsetof(bfr_texture_tile_region, depth));
static_assert(offsetof(TextureTileRegion, tailTile) == offsetof(bfr_texture_tile_region, tail_tile));
static_assert(offsetof(TextureTileRegion, tailTiles) == offsetof(bfr_texture_tile_region, tail_tiles));
static_assert(offsetof(TextureTileRegion, memoryTile) == offsetof(bfr_texture_tile_region, memory_tile));

/// tiles tiles of a sparse buffer from tile mapped to memory from memory_tile, or unmapped, in the
/// buffer's tiles.
struct BufferTileRegion {
    /// 0 is map.
    TileMapping mapping{};
    std::uint64_t tile{};
    std::uint64_t tiles{};
    std::uint64_t memoryTile{};
};
static_assert(sizeof(BufferTileRegion) == sizeof(bfr_buffer_tile_region) && alignof(BufferTileRegion) == alignof(bfr_buffer_tile_region) &&
              std::is_standard_layout_v<BufferTileRegion> && std::is_trivially_copyable_v<BufferTileRegion>);
static_assert(offsetof(BufferTileRegion, mapping) == offsetof(bfr_buffer_tile_region, mapping));
static_assert(offsetof(BufferTileRegion, tile) == offsetof(bfr_buffer_tile_region, tile));
static_assert(offsetof(BufferTileRegion, tiles) == offsetof(bfr_buffer_tile_region, tiles));
static_assert(offsetof(BufferTileRegion, memoryTile) == offsetof(bfr_buffer_tile_region, memory_tile));

/// What bfr_update_tile_mappings sends to one queue: texture_regions of texture and buffer_regions
/// of buffer mapped to memory or unmapped.
struct TileMappingDesc {
    /// The queue to map on, numbered as bfr_device_desc says.
    std::uint32_t queue{};
    /// Tokens the GPU passes before it maps.
    std::span<const Token> waits{};
    /// Null when every region unmaps.
    SparseMemoryRef memory{};
    /// Null for none.
    TextureRef texture{};
    std::span<const TextureTileRegion> textureRegions{};
    /// Null for none.
    BufferRef buffer{};
    std::span<const BufferTileRegion> bufferRegions{};
};

/// How an acceleration structure is built.
struct AccelerationStructureFlags {
    /// 0 is none.
    BuildPreference preference{};
    /// Later builds may update the structure.
    bool allowUpdate{};
    bool minimizeMemory{};
    /// bfr_compact_acceleration_structure may copy it, and its compacted_size be written.
    bool allowCompaction{};
    /// Shaders read its triangles' positions, where bfr_caps_features.ray_position_fetch.
    bool allowDataAccess{};
    /// Of a bottom structure with opacity micromaps, where bfr_caps_features.opacity_micromap:
    /// updates may name other micromaps.
    bool allowOpacityMicromapUpdate{};
    /// Instances may disable its opacity micromaps.
    bool allowDisableOpacityMicromaps{};
    /// Updates may follow its opacity micromaps' data.
    bool allowOpacityMicromapDataUpdate{};
};

/// count micromaps, or triangles naming micromaps, of subdivision_level and format.
struct OpacityMicromapUsage {
    std::uint32_t count{};
    std::uint32_t subdivisionLevel{};
    OpacityMicromapFormat format{};
};
static_assert(sizeof(OpacityMicromapUsage) == sizeof(bfr_opacity_micromap_usage) && alignof(OpacityMicromapUsage) == alignof(bfr_opacity_micromap_usage) &&
              std::is_standard_layout_v<OpacityMicromapUsage> && std::is_trivially_copyable_v<OpacityMicromapUsage>);
static_assert(offsetof(OpacityMicromapUsage, count) == offsetof(bfr_opacity_micromap_usage, count));
static_assert(offsetof(OpacityMicromapUsage, subdivisionLevel) == offsetof(bfr_opacity_micromap_usage, subdivision_level));
static_assert(offsetof(OpacityMicromapUsage, format) == offsetof(bfr_opacity_micromap_usage, format));

/// The micromaps a triangle geometry's triangles take their opacity from: triangle i's is the
/// micromap at the index read from indices (a null indices is i), index_stride bytes apart from
/// index_offset, plus base_triangle, or a bfr_opacity_micromap_special_index. A null micromap is
/// none, where every index is special. usage_count usages from first_usage in the inputs'
/// micromap_usages count the geometry's triangles of each subdivision level and format, passed to
/// backends that take them. None where micromap and indices are both null.
struct TriangleOpacityMicromap {
    AccelerationStructureRef micromap{};
    BufferRef indices{};
    /// Bytes into indices.
    std::uint64_t indexOffset{};
    IndexType indexType{};
    std::uint32_t indexStride{};
    std::uint32_t baseTriangle{};
    std::uint32_t firstUsage{};
    std::uint32_t usageCount{};
};

/// Triangles in a bottom acceleration structure. A null indices is none: triangle_count * 3
/// vertices are read in order. A null transform is none; else a 3x4 row-major float matrix at
/// transform_offset, a multiple of 16. vertex_format is one
/// bfr_format_caps.acceleration_structure_vertices is true for; vertex_offset and vertex_stride are
/// multiples of its component size, index_offset of the index size. The buffers have
/// acceleration_structure_input usage.
struct TriangleGeometry {
    BufferRef vertices{};
    /// Bytes into vertices.
    std::uint64_t vertexOffset{};
    Format vertexFormat{};
    /// Bytes between two vertices.
    std::uint32_t vertexStride{};
    std::uint32_t vertexCount{};
    BufferRef indices{};
    /// Bytes into indices.
    std::uint64_t indexOffset{};
    IndexType indexType{};
    std::uint32_t triangleCount{};
    BufferRef transform{};
    /// Bytes into transform.
    std::uint64_t transformOffset{};
    bool opaque{};
    bool noDuplicateAnyHit{};
    /// Where bfr_caps_features.opacity_micromap.
    TriangleOpacityMicromap opacityMicromap{};
    /// In a structure with motion, the vertices at each keyframe after the first, which vertices
    /// holds: keyframe k's from motion_vertex_offset + (k - 1) * motion_keyframe_stride, laid out
    /// as vertices are. Read only where the inputs' motion_keyframes is not 0. It has
    /// acceleration_structure_input usage.
    BufferRef motionVertices{};
    /// Bytes into motion_vertices.
    std::uint64_t motionVertexOffset{};
    /// Bytes from one keyframe's vertices to the next.
    std::uint64_t motionKeyframeStride{};
};
static_assert(sizeof(TriangleGeometry) == sizeof(bfr_triangle_geometry) && alignof(TriangleGeometry) == alignof(bfr_triangle_geometry) &&
              std::is_standard_layout_v<TriangleGeometry> && std::is_trivially_copyable_v<TriangleGeometry>);
static_assert(offsetof(TriangleGeometry, vertices) == offsetof(bfr_triangle_geometry, vertices));
static_assert(offsetof(TriangleGeometry, vertexOffset) == offsetof(bfr_triangle_geometry, vertex_offset));
static_assert(offsetof(TriangleGeometry, vertexFormat) == offsetof(bfr_triangle_geometry, vertex_format));
static_assert(offsetof(TriangleGeometry, vertexStride) == offsetof(bfr_triangle_geometry, vertex_stride));
static_assert(offsetof(TriangleGeometry, vertexCount) == offsetof(bfr_triangle_geometry, vertex_count));
static_assert(offsetof(TriangleGeometry, indices) == offsetof(bfr_triangle_geometry, indices));
static_assert(offsetof(TriangleGeometry, indexOffset) == offsetof(bfr_triangle_geometry, index_offset));
static_assert(offsetof(TriangleGeometry, indexType) == offsetof(bfr_triangle_geometry, index_type));
static_assert(offsetof(TriangleGeometry, triangleCount) == offsetof(bfr_triangle_geometry, triangle_count));
static_assert(offsetof(TriangleGeometry, transform) == offsetof(bfr_triangle_geometry, transform));
static_assert(offsetof(TriangleGeometry, transformOffset) == offsetof(bfr_triangle_geometry, transform_offset));
static_assert(offsetof(TriangleGeometry, opaque) == offsetof(bfr_triangle_geometry, opaque));
static_assert(offsetof(TriangleGeometry, noDuplicateAnyHit) == offsetof(bfr_triangle_geometry, no_duplicate_any_hit));
static_assert(offsetof(TriangleGeometry, opacityMicromap) == offsetof(bfr_triangle_geometry, opacity_micromap));
static_assert(offsetof(TriangleGeometry, motionVertices) == offsetof(bfr_triangle_geometry, motion_vertices));
static_assert(offsetof(TriangleGeometry, motionVertexOffset) == offsetof(bfr_triangle_geometry, motion_vertex_offset));
static_assert(offsetof(TriangleGeometry, motionKeyframeStride) == offsetof(bfr_triangle_geometry, motion_keyframe_stride));

/// Boxes in a bottom acceleration structure: six floats each, min xyz then max xyz, min at most
/// max, stride bytes apart; offset and stride multiples of 8. The buffer has
/// acceleration_structure_input usage.
struct BoxGeometry {
    BufferRef boxes{};
    /// Bytes into boxes.
    std::uint64_t offset{};
    std::uint32_t stride{};
    std::uint32_t count{};
    bool opaque{};
    bool noDuplicateAnyHit{};
};
static_assert(sizeof(BoxGeometry) == sizeof(bfr_box_geometry) && alignof(BoxGeometry) == alignof(bfr_box_geometry) &&
              std::is_standard_layout_v<BoxGeometry> && std::is_trivially_copyable_v<BoxGeometry>);
static_assert(offsetof(BoxGeometry, boxes) == offsetof(bfr_box_geometry, boxes));
static_assert(offsetof(BoxGeometry, offset) == offsetof(bfr_box_geometry, offset));
static_assert(offsetof(BoxGeometry, stride) == offsetof(bfr_box_geometry, stride));
static_assert(offsetof(BoxGeometry, count) == offsetof(bfr_box_geometry, count));
static_assert(offsetof(BoxGeometry, opaque) == offsetof(bfr_box_geometry, opaque));
static_assert(offsetof(BoxGeometry, noDuplicateAnyHit) == offsetof(bfr_box_geometry, no_duplicate_any_hit));

/// A partitioned top structure's counts and work: instance_count instances, in partition_count
/// partitions of at most max_partition_instances each and the global partition of at most
/// max_global_instances, partition_count plus max_global_instances at most
/// bfr_caps_ray_tracing.max_partitions; with partition_translation, partitions may be moved. A
/// build runs the bfr_partitioned_top_op records from op_offset in ops, as many as the GPU reads
/// from the u32 at op_count_offset, a multiple of 4, in op_count; both buffers are given, with
/// acceleration_structure_input usage. bfr_get_acceleration_structure_sizes reads the flags, the
/// counts and partition_translation.
struct PartitionedTopInputs {
    std::uint32_t instanceCount{};
    std::uint32_t maxPartitionInstances{};
    std::uint32_t partitionCount{};
    std::uint32_t maxGlobalInstances{};
    bool partitionTranslation{};
    BufferRef ops{};
    /// Bytes into ops.
    std::uint64_t opOffset{};
    BufferRef opCount{};
    /// Bytes into op_count.
    std::uint64_t opCountOffset{};
};

/// The upper bounds a cluster operation of clusters or templates is sized for: vertices of
/// vertex_format, geometry indices to max_geometry_index, at most max_unique_geometries of them,
/// max_triangles triangles and max_vertices vertices in each, at most
/// bfr_caps_ray_tracing.max_cluster_triangles and max_cluster_vertices, max_total_triangles and
/// max_total_vertices in all, and no record truncating fewer than min_truncate_bits position bits,
/// at most 32.
struct ClusterTriangleLimits {
    Format vertexFormat{};
    std::uint32_t maxGeometryIndex{};
    std::uint32_t maxUniqueGeometries{};
    std::uint32_t maxTriangles{};
    std::uint32_t maxVertices{};
    std::uint32_t maxTotalTriangles{};
    std::uint32_t maxTotalVertices{};
    std::uint32_t minTruncateBits{};
};

/// The upper bounds a build_bottoms is sized for: max_total_clusters clusters in all,
/// max_clusters_per_bottom in each bottom structure.
struct ClusterBottomLimits {
    std::uint32_t maxTotalClusters{};
    std::uint32_t maxClustersPerBottom{};
};

/// What a move moves, and at most max_bytes of it; with no_overlap, no destination overlaps a
/// source, which stays valid, as after a copy.
struct ClusterMoveLimits {
    /// 0 is bottom.
    ClusterStructureType type{};
    bool noOverlap{};
    std::uint64_t maxBytes{};
};

/// A cluster operation's kind, mode and upper bounds: at most max_count structures, built with
/// flags as other structures are; with allow_opacity_micromaps, clusters may name opacity
/// micromaps. The bounds the operation reads: move for move, bottoms for build_bottoms, triangles
/// for the rest.
struct ClusterInputs {
    /// 0 is move.
    ClusterOperation operation{};
    /// 0 is implicit_destinations.
    ClusterMode mode{};
    AccelerationStructureFlags flags{};
    bool allowOpacityMicromaps{};
    std::uint32_t maxCount{};
    ClusterMoveLimits move{};
    ClusterBottomLimits bottoms{};
    ClusterTriangleLimits triangles{};
};

/// Which of a bfr_cluster_build's regions hold, at their offset, the address of the data rather
/// than the data, which the GPU reads as it runs.
struct ClusterIndirection {
    bool destination{};
    bool scratch{};
    bool addresses{};
    bool sizes{};
    bool records{};
    bool count{};
};

/// A cluster operation, from inputs: the records of its kind from record_offset in records,
/// record_stride bytes apart (0 packed), as many as the u32 at count_offset, a multiple of 4, in
/// count, or with no count max_count, never more than max_count; records and count have
/// acceleration_structure_input usage. implicit_destinations packs the structures from
/// destination_offset in destination, which has acceleration_structure_storage usage and at least
/// the size query's size bytes, or for a move the bytes moved, and writes their addresses to
/// addresses and their sizes to sizes, where given; explicit_destinations reads each structure's
/// address from addresses, each in a buffer with acceleration_structure_storage usage, and its size
/// from sizes, where given; compute_sizes writes each structure's size to sizes. Each destination
/// is a multiple of bfr_caps_ray_tracing.cluster_alignment for clusters, cluster_template_alignment
/// for templates and cluster_bottom_alignment for bottom structures. addresses holds 8-byte
/// addresses address_stride bytes apart, at least 8, and has storage usage; sizes holds 4-byte
/// sizes size_stride bytes apart, at least 4. Each of addresses, sizes and records is read or
/// written within its buffer, from its offset. Scratch is scratch_offset bytes into scratch, which
/// has acceleration_structure_scratch usage, at least the size query's build_scratch bytes, a
/// multiple of bfr_caps_ray_tracing.cluster_scratch_alignment, and overlaps no destination.
struct ClusterBuild {
    ClusterInputs inputs{};
    BufferRef destination{};
    /// Bytes into destination.
    std::uint64_t destinationOffset{};
    BufferRef scratch{};
    /// Bytes into scratch.
    std::uint64_t scratchOffset{};
    BufferRef addresses{};
    /// Bytes into addresses.
    std::uint64_t addressOffset{};
    std::uint64_t addressStride{};
    BufferRef sizes{};
    /// Bytes into sizes.
    std::uint64_t sizeOffset{};
    std::uint64_t sizeStride{};
    BufferRef records{};
    /// Bytes into records.
    std::uint64_t recordOffset{};
    std::uint64_t recordStride{};
    BufferRef count{};
    /// Bytes into count.
    std::uint64_t countOffset{};
    ClusterIndirection indirection{};
};

/// What an acceleration structure is built from. A bottom one holds triangles or boxes, not both; a
/// geometry's index in its array is the geometry index a hit group is chosen by. A top one holds
/// instance_count instance records from instance_offset, a multiple of 16, in instances, which has
/// acceleration_structure_input usage, laid out as bfr_write_instances writes them. A bottom one's
/// triangles name their micromaps' usages in micromap_usages. An opacity micromap holds
/// micromap_usages' micromaps: bfr_opacity_micromap_records, micromap_record_stride bytes apart
/// from micromap_record_offset in micromap_records, whose states micromap_data holds from
/// micromap_data_offset; both buffers have acceleration_structure_input usage, both offsets
/// multiples of 256. A partitioned top one is built from partitioned.
/// bfr_get_acceleration_structure_sizes reads the counts, formats, flags, usages and whether a
/// transform is given.
struct AccelerationStructureInputs {
    /// 0 is bottom.
    AccelerationStructureType type{};
    AccelerationStructureFlags flags{};
    /// Read during the call only.
    std::span<const TriangleGeometry> triangles{};
    /// Read during the call only.
    std::span<const BoxGeometry> boxes{};
    BufferRef instances{};
    /// Bytes into instances.
    std::uint64_t instanceOffset{};
    std::uint32_t instanceCount{};
    /// Read during the call only.
    std::span<const OpacityMicromapUsage> micromapUsages{};
    BufferRef micromapData{};
    /// Bytes into micromap_data.
    std::uint64_t micromapDataOffset{};
    BufferRef micromapRecords{};
    /// Bytes into micromap_records.
    std::uint64_t micromapRecordOffset{};
    std::uint32_t micromapRecordStride{};
    /// The structure's bfr_acceleration_structure_desc.motion_keyframes: its triangles' motion
    /// vertices are read, or its instance records are bfr_write_motion_instances'.
    std::uint32_t motionKeyframes{};
    PartitionedTopInputs partitioned{};
};

/// The bytes an acceleration structure takes, and the scratch bytes its build and its update take.
/// discardable: the backend says an opacity micromap may be destroyed once the structures built
/// with it are built.
struct AccelerationStructureSizes {
    std::uint64_t size{};
    std::uint64_t buildScratch{};
    std::uint64_t updateScratch{};
    bool discardable{};
};

/// What a backend needs to make an acceleration structure again at the reference it had, as
/// bfr_capture_acceleration_structure gives it: opaque, the same on every backend. All zero is
/// none.
struct AccelerationStructureCapture {
    std::array<std::uint64_t, BFR_ACCELERATION_STRUCTURE_CAPTURE_WORDS> words{};
};

/// How to create an acceleration structure of size bytes, in memory the device allocates. With
/// motion_keyframes, at most bfr_caps_ray_tracing.max_motion_keyframes, where
/// bfr_caps_features.ray_tracing_motion, its builds have motion: a bottom one's triangles move
/// between keyframes, a top one holds motion instances, at most motion_instances of them, passed to
/// backends that take it. 0 is none. With capture_replay, where
/// bfr_caps_features.acceleration_structure_capture_replay, its reference may be captured, by
/// bfr_capture_acceleration_structure, and replayed: with replay, what that gave for a structure
/// made with this desc but replay, on a device of the same adapter opened with the same queues, it
/// is made at the reference that one had, or fails where the backend cannot give it. An opacity
/// micromap has none where the backend gives it no reference (Vulkan).
struct AccelerationStructureDesc {
    /// 0 is bottom.
    AccelerationStructureType type{};
    /// Bytes, as bfr_get_acceleration_structure_sizes gives them.
    std::uint64_t size{};
    std::uint32_t motionKeyframes{};
    std::uint32_t motionInstances{};
    bool captureReplay{};
    /// All zero is none.
    AccelerationStructureCapture replay{};
};

/// A build of dst, of inputs' type, from inputs; or, with update, an update of src into dst (they
/// may be the same), src built with allow_update and inputs as its last build gave them but for the
/// data the buffers hold. A partitioned top one's update starts from src, a partitioned top one
/// built before, with no allow_update; its build starts from none. Scratch is scratch_offset bytes
/// into scratch, which has acceleration_structure_scratch usage, a multiple of
/// bfr_caps_ray_tracing.scratch_alignment, and of 256 for a partitioned top one, at least the
/// build's or update's scratch bytes, the build's for both of a partitioned top one, and overlaps
/// neither structure.
struct AccelerationStructureBuild {
    AccelerationStructureRef dst{};
    AccelerationStructureRef src{};
    bool update{};
    AccelerationStructureInputs inputs{};
    BufferRef scratch{};
    /// Bytes into scratch.
    std::uint64_t scratchOffset{};
};

/// One instance of a bottom acceleration structure in a top one.
struct AccelerationStructureInstance {
    /// 3x4 row-major object-to-world transform.
    std::array<float, BFR_TRANSFORM_FLOATS> transform{};
    /// What the shader reads as the instance's custom index; below instance_index_limit.
    std::uint32_t customIndex{};
    /// Rays whose mask ANDs to 0 with it miss the instance.
    std::uint8_t mask{};
    /// The instance's offset, in records, into the hit region; below instance_index_limit.
    std::uint32_t hitGroupOffset{};
    bool cullDisable{};
    bool frontCounterClockwise{};
    /// 0 is as each geometry says.
    InstanceOpacity opacity{};
    /// Its opacity micromaps' unknown states are taken as known, where
    /// bfr_caps_features.opacity_micromap.
    bool forceOpacityMicromap2State{};
    /// Its opacity micromaps are ignored, of a bottom structure built with
    /// allow_disable_opacity_micromaps.
    bool disableOpacityMicromaps{};
    /// Null, with no bottom_reference, is an instance no ray hits.
    AccelerationStructureRef bottomStructure{};
    /// Where bottom_structure is null, what the instance names its bottom structure by, for one BFR
    /// holds no handle to, such as a cluster bottom structure (bfr_build_clusters).
    std::uint64_t bottomReference{};
};
static_assert(sizeof(AccelerationStructureInstance) == sizeof(bfr_acceleration_structure_instance) && alignof(AccelerationStructureInstance) == alignof(bfr_acceleration_structure_instance) &&
              std::is_standard_layout_v<AccelerationStructureInstance> && std::is_trivially_copyable_v<AccelerationStructureInstance>);
static_assert(offsetof(AccelerationStructureInstance, transform) == offsetof(bfr_acceleration_structure_instance, transform));
static_assert(offsetof(AccelerationStructureInstance, customIndex) == offsetof(bfr_acceleration_structure_instance, custom_index));
static_assert(offsetof(AccelerationStructureInstance, mask) == offsetof(bfr_acceleration_structure_instance, mask));
static_assert(offsetof(AccelerationStructureInstance, hitGroupOffset) == offsetof(bfr_acceleration_structure_instance, hit_group_offset));
static_assert(offsetof(AccelerationStructureInstance, cullDisable) == offsetof(bfr_acceleration_structure_instance, cull_disable));
static_assert(offsetof(AccelerationStructureInstance, frontCounterClockwise) == offsetof(bfr_acceleration_structure_instance, front_counter_clockwise));
static_assert(offsetof(AccelerationStructureInstance, opacity) == offsetof(bfr_acceleration_structure_instance, opacity));
static_assert(offsetof(AccelerationStructureInstance, forceOpacityMicromap2State) == offsetof(bfr_acceleration_structure_instance, force_opacity_micromap_2_state));
static_assert(offsetof(AccelerationStructureInstance, disableOpacityMicromaps) == offsetof(bfr_acceleration_structure_instance, disable_opacity_micromaps));
static_assert(offsetof(AccelerationStructureInstance, bottomStructure) == offsetof(bfr_acceleration_structure_instance, bottom_structure));
static_assert(offsetof(AccelerationStructureInstance, bottomReference) == offsetof(bfr_acceleration_structure_instance, bottom_reference));

/// A transform as its parts: scale, the shears a (xy), b (xz) and c (yz), and a pivot added after
/// them, then a rotation quaternion (x, y, z, w) about the origin and a translation. Keyframes
/// between are blended part by part.
struct SrtTransform {
    std::array<float, 3> scale{};
    std::array<float, 3> shear{};
    std::array<float, 3> pivot{};
    std::array<float, 4> rotation{};
    std::array<float, 3> translation{};
};

/// One keyframe of a motion instance's transform: matrix for matrix motion, srt for srt motion.
