    /// A shading rate per screen tile, from a texture.
    bool shadingRateTexture{};
    bool shaderFloat16{};
    bool shaderFloat64{};
    bool shaderInt8{};
    bool shaderInt16{};
    bool shaderInt64{};
    /// 64-bit integer atomics on buffers.
