inline Expected<std::uint64_t> AccelerationStructure::accelerationStructureReference() {
    uint64_t reference{};
    if (const bfr_result result = bfr_get_acceleration_structure_reference(device_, accelerationStructure_, &reference); result < 0) {
        return std::unexpected(detail::failure(result));
    }
    return reference;
}

inline Expected<AccelerationStructureCapture> AccelerationStructure::capture() {
    bfr_acceleration_structure_capture capture{};
    if (const bfr_result result = bfr_capture_acceleration_structure(device_, accelerationStructure_, &capture); result < 0) {
        return std::unexpected(detail::failure(result));
    }
    return detail::fromC(capture);
}

inline Expected<std::vector<std::uint8_t>> PipelineCache::pipelineCacheData() {
    std::vector<uint8_t> dataC;
    std::size_t size = 0;
    // Asked again while the list grows between the two calls.
    for (;;) {
        bfr_result result = bfr_get_pipeline_cache_data(device_, pipelineCache_, &size, nullptr);
        if (result < 0) {
            return std::unexpected(detail::failure(result));
        }
        // None to fill: a null array would ask the count again.
        if (size == 0) {
            break;
        }
        dataC.resize(size);
        result = bfr_get_pipeline_cache_data(device_, pipelineCache_, &size, dataC.data());
        if (result < 0) {
            return std::unexpected(detail::failure(result));
        }
        if (result != BFR_RESULT_INCOMPLETE) {
            break;
        }
    }
    std::vector<std::uint8_t> data;
    data.reserve(size);
    for (std::size_t i = 0; i < size; ++i) {
        data.push_back(dataC[i]);
    }
    return data;
}

/// Lists the backends this build has, in bfr_backend order.
[[nodiscard]] inline Expected<std::vector<Backend>> backends() {
    std::vector<bfr_backend> backendsC;
    std::uint32_t count = 0;
    // Asked again while the list grows between the two calls.
    for (;;) {
        bfr_result result = bfr_get_backends(&count, nullptr);
        if (result < 0) {
            return std::unexpected(detail::failure(result));
        }
        // None to fill: a null array would ask the count again.
        if (count == 0) {
            break;
        }
        backendsC.resize(count);
        result = bfr_get_backends(&count, backendsC.data());
        if (result < 0) {
            return std::unexpected(detail::failure(result));
        }
        if (result != BFR_RESULT_INCOMPLETE) {
            break;
        }
    }
    std::vector<Backend> backends;
    backends.reserve(count);
    for (std::uint32_t i = 0; i < count; ++i) {
        backends.push_back(static_cast<Backend>(backendsC[i]));
    }
    return backends;
}

